const lecon = $('Fetch Lecon').first().json;
const contents = $('Fetch Contents').all().map(i => i.json);
const action = $('Webhook').first().json.body.action || 'explain';
const question = $('Webhook').first().json.body.question || '';

// Build a comprehensive knowledge block for the AI
let context = `TITRE DE LA LECON: ${lecon.titre}\n`;
context += `DESCRIPTION: ${lecon.description || 'N/A'}\n\n`;
context += `CONTENU DETAILLÉ:\n`;

contents.forEach((c, i) => {
  context += `--- Element ${i+1} (${c.type}) ---\n`;
  context += `Titre: ${c.title}\n`;
  if (c.description) context += `Description: ${c.description}\n`;
  if (c.url) context += `Source: ${c.url}\n`;
  context += `\n`;
});

return [{ json: { context, action, question, leconTitle: lecon.titre } }];

